     6	import hotel.rooms.Room;
     7	import hotel.rooms.Rooms;
     8	import java.math.BigDecimal;
     9	import java.time.LocalDate;
    10	
    11	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    12	public final class ReservationService {
    13	
    14	    static final String HOTEL_NAME = "Pousada Maré Alta";
    15	
    16	    private final Rooms rooms;
    17	    private final ReservationStore store;
    18	    private final PriceCalculator priceCalculator;
    19	    private final EmailSender emailSender;
    20	
    21	    public ReservationService(
    22	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    23	        this.rooms = rooms;
    24	        this.store = store;
    25	        this.priceCalculator = priceCalculator;
    26	        this.emailSender = emailSender;
    27	    }
    28	
    29	    public synchronized Reservation create(NewReservation request) {
    30	        if (!request.checkOut().isAfter(request.checkIn())) {
    31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    32	        }
    33	        if (request.guests() < 1) {
    34	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    35	        }
    36	        Room room = rooms.find(request.roomNumber())
    37	                .orElseThrow(() -> new HotelException(
    38	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    39	        if (request.guests() > room.capacity()) {
    40	            throw new HotelException(
    41	                    ErrorCode.CAPACITY_EXCEEDED,
    42	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    43	        }
    44	        boolean roomTaken = store.all().stream()
    45	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    46	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    47	        if (roomTaken) {
    48	            throw new HotelException(
    49	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    50	        }
    51	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    52	        Reservation reservation = new Reservation(store.nextId(), request, price);
    53	        store.save(reservation);
    54	        return reservation;
    55	    }
    56	
    57	    public Reservation find(long reservationId) {
    58	        return store.find(reservationId)
    59	                .orElseThrow(() -> new HotelException(
    60	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    61	    }
    62	
    63	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    64	    public synchronized Reservation confirm(long reservationId) {
    65	        Reservation reservation = find(reservationId);
    66	        if (reservation.status() != ReservationStatus.PENDING) {
    67	            throw notAllowed(reservation, "confirm");
    68	        }
    69	        reservation.confirmPayment();
    70	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    71	        emailSender.send(
    72	                reservation.guest().email(),
    73	                "Reserva confirmada - " + HOTEL_NAME,
    74	                confirmationEmailBody(reservation, receipt));
    75	
    76	        Room room = roomOf(reservation);
    77	        emailSender.send(
    78	                "governanca@pousadamarealta.com.br",
    79	                "Reserva confirmada - quarto " + room.number(),
    80	                governanceConfirmationEmailBody(reservation));
    81	
    82	        emailSender.send(
    83	                "financeiro@pousadamarealta.com.br",
    84	                "Pagamento recebido - reserva " + reservation.id(),
    85	                financeConfirmationEmailBody(reservation));
    86	
    87	        return reservation;
    88	    }
    89	
    90	    /**
    91	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    92	     * reservation was never paid, so nothing comes back).
    93	     */
    94	    public synchronized Reservation cancel(long reservationId) {
    95	        Reservation reservation = find(reservationId);
    96	        if (reservation.status() != ReservationStatus.PENDING
    97	                && reservation.status() != ReservationStatus.CONFIRMED) {
    98	            throw notAllowed(reservation, "cancel");
    99	        }
   100	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
   101	        BigDecimal refund = switch (reservation.ratePlan()) {
   102	            case STANDARD -> reservation.amountPaid();
   103	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
   104	        };
   105	        reservation.cancel(refund);
   106	
   107	        if (wasConfirmed) {
   108	            Room room = roomOf(reservation);
   109	            emailSender.send(
   110	                    "governanca@pousadamarealta.com.br",
   111	                    "Reserva cancelada - quarto " + room.number(),
   112	                    governanceCancellationEmailBody(reservation));
   113	
   114	            if (refund.signum() > 0) {
   115	                emailSender.send(
   116	                        "financeiro@pousadamarealta.com.br",
   117	                        "Reembolso - reserva " + reservation.id(),
   118	                        financeCancellationEmailBody(reservation, refund));
   119	            }
   120	        }
   121	
   122	        return reservation;
   123	    }
   124	
   125	    public synchronized Reservation checkIn(long reservationId) {
